window.zone_elements={lib:{},assets:[],shapes:{},setup:function(h){
const n=h.MovieClip,e=h.Container,a=h.Sprite,z=h.Text,A=h.Graphics;

// ── HP bar ─────────────────────────────────────────────────────────
zone_elements.lib.Hp_bar=class extends e{
  constructor(w,ht,color){
    super();this._maxW=w;color=color||0x338833;
    const bg=new A();bg.beginFill(0x0a100a,1);bg.drawRoundedRect(0,0,w,ht,2);bg.endFill();
    this.fill=new A();this.fill.beginFill(color,1);this.fill.drawRoundedRect(0,0,w,ht,2);this.fill.endFill();
    const brd=new A();brd.lineStyle(1,0x224422,0.7);brd.drawRoundedRect(0,0,w,ht,2);
    this.addChild(bg,this.fill,brd);
    this[this.fill.name='fill']=this.fill;
  }
  setPercent(p){this.fill.scale.x=Math.max(0,Math.min(1,p));}
};

// ── Вкладка локации ────────────────────────────────────────────────
zone_elements.lib.Zone_tab=class extends e{
  constructor(label,w){
    super();
    this._w=w;
    this.bg=new A();
    this._draw(false);
    const t=new z(label,{fontFamily:'Southbank LT',fontSize:13,fontWeight:'bold',fill:'#a0c080',align:'center',wordWrap:true,wordWrapWidth:w-8,dropShadow:true,dropShadowDistance:1,dropShadowColor:'#000'});
    t.anchor.set(0.5,0.5);t.x=w/2;t.y=20;
    this[t.name='label_txt']=t;
    this.addChild(this.bg,t);
    this.interactive=true;this.buttonMode=true;
    this.on('mouseover',()=>{if(!this._active)this._draw('hover');});
    this.on('mouseout',()=>{if(!this._active)this._draw(false);});
  }
  _draw(state){
    this.bg.clear();
    if(state==='active'){this.bg.beginFill(0x1a3a1a,1);this.bg.lineStyle(1,0x4a8a4a);}
    else if(state==='hover'){this.bg.beginFill(0x0f260f,1);this.bg.lineStyle(1,0x2a5a2a,0.7);}
    else{this.bg.beginFill(0x080f08,0.9);this.bg.lineStyle(1,0x1a2e1a,0.6);}
    this.bg.drawRoundedRect(0,0,this._w,38,4);this.bg.endFill();
  }
  setActive(v){this._active=v;this._draw(v?'active':false);}
};

// ── Карточка КПП ───────────────────────────────────────────────────
zone_elements.lib.Checkpoint_card=class extends e{
  constructor(){
    super();
    // Фон карточки
    this.bg=new A();
    this.bg.beginFill(0x0a160a,0.9);this.bg.lineStyle(1,0x1e3c1e,0.8);this.bg.drawRoundedRect(0,0,374,148,5);this.bg.endFill();
    this.addChild(this.bg);
    // Номер / название
    const nt=new z('',{fontFamily:'Southbank LT',fontSize:14,fontWeight:'bold',fill:'#c8d890',dropShadow:true,dropShadowDistance:1,dropShadowColor:'#000'});
    nt.x=10;nt.y=8;this[nt.name='name_txt']=nt;
    // Уровень
    const lt=new z('',{fontFamily:'Southbank LT',fontSize:11,fill:'#6a8a5a'});lt.x=10;lt.y=28;
    this[lt.name='level_txt']=lt;
    // HP bar
    const hp=new zone_elements.lib.Hp_bar(354,10,0x338833);hp.x=10;hp.y=46;
    this[hp.name='hp_bar']=hp;
    // HP числа
    const hpt=new z('',{fontFamily:'Arial',fontSize:11,fill:'#80aa60'});hpt.x=10;hpt.y=60;
    this[hpt.name='hp_txt']=hpt;
    // Награда
    const rt=new z('',{fontFamily:'Arial',fontSize:11,fill:'#a09050',wordWrap:true,wordWrapWidth:354});rt.x=10;rt.y=80;
    this[rt.name='reward_txt']=rt;
    // Статус (заблокировано)
    const st=new z('',{fontFamily:'Southbank LT',fontSize:13,fill:'#4a6a4a',align:'center',wordWrap:true,wordWrapWidth:354});
    st.anchor.set(0.5,0.5);st.x=187;st.y=74;
    this[st.name='status_txt']=st;
    // Кнопка атаки
    const abg=new A();abg.beginFill(0x1a3a10,1);abg.lineStyle(1,0x3a7a20);abg.drawRoundedRect(0,0,110,32,4);abg.endFill();
    const at=new z('АТАКОВАТЬ',{fontFamily:'Southbank LT',fontSize:11,fontWeight:'bold',fill:'#b0e060',align:'center'});at.anchor.set(0.5,0.5);at.x=55;at.y=16;
    const ab=new e();ab.addChild(abg,at);ab.x=132;ab.y=108;
    ab.interactive=true;ab.buttonMode=true;
    ab.on('mouseover',()=>abg.tint=0xcceeaa);ab.on('mouseout',()=>abg.tint=0xffffff);
    this[ab.name='butt_attack']=ab;
    // Кнопка захватить (финальный КПП)
    const cbg=new A();cbg.beginFill(0x3a1a10,1);cbg.lineStyle(1,0x7a4020);cbg.drawRoundedRect(0,0,110,32,4);cbg.endFill();
    const ct=new z('ЗАХВАТИТЬ',{fontFamily:'Southbank LT',fontSize:11,fontWeight:'bold',fill:'#e09060',align:'center'});ct.anchor.set(0.5,0.5);ct.x=55;ct.y=16;
    const cb=new e();cb.addChild(cbg,ct);cb.x=252;cb.y=108;
    cb.interactive=true;cb.buttonMode=true;cb.visible=false;
    cb.on('mouseover',()=>cbg.tint=0xeeccaa);cb.on('mouseout',()=>cbg.tint=0xffffff);
    this[cb.name='butt_capture']=cb;
    this.addChild(nt,lt,hp,hpt,rt,st,ab,cb);
  }
  setLocked(v){
    this.hp_bar.visible=!v;this.hp_txt.visible=!v;
    this.reward_txt.visible=!v;this.butt_attack.visible=!v;
    this.status_txt.text=v?'[ ЗАБЛОКИРОВАНО ]':'';
    if(v){this.bg.clear();this.bg.beginFill(0x060c06,0.7);this.bg.lineStyle(1,0x111e11,0.5);this.bg.drawRoundedRect(0,0,374,148,5);this.bg.endFill();}
    else{this.bg.clear();this.bg.beginFill(0x0a160a,0.9);this.bg.lineStyle(1,0x1e3c1e,0.8);this.bg.drawRoundedRect(0,0,374,148,5);this.bg.endFill();}
  }
};

// ── Бизнес-панель ──────────────────────────────────────────────────
zone_elements.lib.Business_panel=class extends e{
  constructor(){
    super();
    const bg=new A();bg.beginFill(0x08120a,0.95);bg.lineStyle(1,0x2a4a2a,0.7);bg.drawRoundedRect(0,0,1180,54,5);bg.endFill();
    this.addChild(bg);
    const lbl=new z('БИЗНЕС:',{fontFamily:'Southbank LT',fontSize:12,fill:'#6a8a5a',letterSpacing:2});lbl.x=12;lbl.y=8;
    const nt=new z('',{fontFamily:'Southbank LT',fontSize:13,fontWeight:'bold',fill:'#c8b860'});nt.x=92;nt.y=7;
    this[nt.name='name_txt']=nt;
    const it=new z('',{fontFamily:'Arial',fontSize:12,fill:'#8aaa60'});it.x=92;it.y=28;
    this[it.name='income_txt']=it;
    const ubg=new A();ubg.beginFill(0x1a3a10,1);ubg.lineStyle(1,0x3a7a20);ubg.drawRoundedRect(0,0,130,36,4);ubg.endFill();
    const ut=new z('УЛУЧШИТЬ',{fontFamily:'Southbank LT',fontSize:12,fontWeight:'bold',fill:'#b0e060',align:'center'});ut.anchor.set(0.5,0.5);ut.x=65;ut.y=18;
    const ub=new e();ub.addChild(ubg,ut);ub.x=1034;ub.y=9;
    ub.interactive=true;ub.buttonMode=true;
    ub.on('mouseover',()=>ubg.tint=0xcceeaa);ub.on('mouseout',()=>ubg.tint=0xffffff);
    const ct=new z('',{fontFamily:'Southbank LT',fontSize:11,fill:'#c8a840'});ct.x=860;ct.y=17;
    this[nt.name='name_txt']=nt;this[it.name='income_txt']=it;
    this[ub.name='butt_upgrade']=ub;this[ct.name='cost_txt']=ct;
    this.addChild(lbl,nt,it,ub,ct);
  }
};

// ── Главное окно Зоны ──────────────────────────────────────────────
zone_elements.lib.Zone_win=class extends e{
  constructor(){
    super();
    // Фон окна
    const wb=new A();wb.beginFill(0x060e06,0.97);wb.lineStyle(2,0x2a5a2a,0.9);wb.drawRoundedRect(0,0,1200,524,6);wb.endFill();
    this.addChild(wb);
    // Хедер
    const hb=new A();hb.beginFill(0x0a1e0a,1);hb.drawRect(2,2,1196,42);hb.endFill();
    const hl=new A();hl.lineStyle(1,0x2a5a2a,0.5);hl.moveTo(2,45);hl.lineTo(1198,45);
    this.addChild(hb,hl);
    const ttl=new z('ЗОНА',{fontFamily:'Southbank LT',fontSize:18,fontWeight:'bold',fill:'#c8e060',letterSpacing:5,dropShadow:true,dropShadowDistance:2,dropShadowColor:'#000'});
    ttl.x=20;ttl.y=12;this.addChild(ttl);
    // Кнопка закрыть
    const cbg=new A();cbg.beginFill(0x3a1010,1);cbg.lineStyle(1,0x882222);cbg.drawRoundedRect(0,0,30,30,4);cbg.endFill();
    const ctx=new z('×',{fontFamily:'Arial',fontSize:22,fill:'#cc4444'});ctx.anchor.set(0.5,0.5);ctx.x=15;ctx.y=15;
    const cl=new e();cl.addChild(cbg,ctx);cl.x=1162;cl.y=7;
    cl.interactive=true;cl.buttonMode=true;
    cl.on('mouseover',()=>cbg.tint=0xddaaaa);cl.on('mouseout',()=>cbg.tint=0xffffff);
    this[cl.name='butt_close']=cl;this.addChild(cl);
    // Вкладки локаций (5 штук)
    const tabs_names=['Кордон','Свалка','Агропром','Дикая Тер.','ЧАЭС'];
    const tw=231,tgap=4;
    const tabs=new e();tabs.x=10;tabs.y=48;
    for(let i=0;i<5;i++){
      const tb=new zone_elements.lib.Zone_tab(tabs_names[i],tw);
      tb.x=i*(tw+tgap);tabs['tab_'+i]=tb;tabs.addChild(tb);
    }
    this[tabs.name='tabs']=tabs;this.addChild(tabs);
    // Разделитель под вкладками
    const tdiv=new A();tdiv.lineStyle(1,0x2a4a2a,0.5);tdiv.moveTo(10,89);tdiv.lineTo(1190,89);
    this.addChild(tdiv);
    // Сетка КПП (6 карточек: 3 × 2)
    const grid=new e();grid.x=10;grid.y=95;
    for(let i=0;i<6;i++){
      const cd=new zone_elements.lib.Checkpoint_card();
      cd.x=(i%3)*(374+8);cd.y=Math.floor(i/3)*(148+8);
      grid['card_'+i]=cd;grid.addChild(cd);
    }
    this[grid.name='cp_grid']=grid;this.addChild(grid);
    // Бизнес-панель
    const biz=new zone_elements.lib.Business_panel();biz.x=10;biz.y=460;
    this[biz.name='business']=biz;this.addChild(biz);
  }
};

// ── Root MovieClip ─────────────────────────────────────────────────
zone_elements.lib.zone_elements=class extends n{
  constructor(){
    super({duration:1,framerate:30});
    const b=new zone_elements.lib.Zone_win();
    this[b.name='zone_win']=b;this.addChild(b);
  }
};
zone_elements.stage=zone_elements.lib.zone_elements}};
